<?phpsession_start();if (!isset($_SESSION['admin_connecte']) || $_SESSION['admin_connecte'] !== true) {    header("Location: login.php");    exit();}// --- SÉCURITÉ SESSION ---if (!isset($_SESSION['id_admin'])) {    die("Erreur de session : Veuillez vous reconnecter.");}$id_utilisateur = $_SESSION['id_admin'];// ==========================================// 1. LECTURE DES SEUILS DYNAMIQUES (config.json)// ==========================================$fichier_config = 'config.json';$seuil_froid = 34.0; // Valeurs par défaut$seuil_chaud = 35.5;if (file_exists($fichier_config)) {    $config_actuelle = json_decode(file_get_contents($fichier_config), true);    if(isset($config_actuelle['seuil_froid'])) $seuil_froid = floatval($config_actuelle['seuil_froid']);    if(isset($config_actuelle['seuil_chaud'])) $seuil_chaud = floatval($config_actuelle['seuil_chaud']);}// ==========================================// 2. CONNEXION BDD ET VÉRIFICATION DES DROITS// ==========================================$host = "127.0.0.1";$dbname = "madeb2677953_2zjnm";$user = "madeb2677953_2zjnm";$pass = "wddzero3it";$mes_ruches = [];$temp_beta = 31.2; $poids_beta = 36.5;try {    $pdo = new PDO("mysql:host=$host;dbname=$dbname;charset=utf8", $user, $pass);        // On regarde quelles ruches (1 ou 2) possède cet utilisateur    $stmt_check = $pdo->prepare("SELECT id_ruche FROM ruche WHERE id_admin = :id");    $stmt_check->execute(['id' => $id_utilisateur]);    while($row = $stmt_check->fetch(PDO::FETCH_ASSOC)) {        $mes_ruches[] = (int)$row['id_ruche'];    }    // Si l'utilisateur possède Beta (ID 2), on va chercher les vraies données    if (in_array(2, $mes_ruches)) {        $stmt_beta = $pdo->query("SELECT temperature, poids FROM mesures WHERE id_ruche = 2 ORDER BY id_mesure DESC LIMIT 1");        $data_beta = $stmt_beta->fetch();        if ($data_beta) {            $temp_beta = floatval($data_beta['temperature']);            $poids_beta = floatval($data_beta['poids']);        }    }} catch(PDOException $e) {    // Valeurs par défaut en cas d'erreur}// Calcul automatique du pourcentage de récolte pour Beta$pct_beta = round(($poids_beta / 40.0) * 100);if($pct_beta > 100) $pct_beta = 100;if($pct_beta < 0) $pct_beta = 0;if($pct_beta >= 100) { $hMsg_beta = "PRÊT À RÉCOLTER"; }elseif($pct_beta > 75) { $hMsg_beta = "RÉCOLTE IMMINENTE"; }else { $hMsg_beta = "CROISSANCE EN COURS"; }?><!DOCTYPE html><html lang="fr"><head>    <meta charset="UTF-8">    <meta name="viewport" content="width=device-width, initial-scale=1.0">    <title>BEE WEB // MONITORING AI</title>    <link rel="stylesheet" href="style_app.css">    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>    <style>        /* --- LAYOUT EXACT D'ORIGINE --- */        .dash-grid { display: grid; grid-template-columns: 320px 1fr; gap: 30px; flex: 1; align-items: stretch; }        .right-panel { display: flex; flex-direction: column; flex: 1; }        .cyber-card { background: var(--panel-glass); border: 1px solid var(--border-glass); border-radius: 12px; padding: 25px; backdrop-filter: blur(10px); display: flex; flex-direction: column; overflow: hidden; }        .ai-status { text-align: center; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid var(--border-glass); }        .ai-avatar { width: 80px; height: 80px; border-radius: 50%; margin: 0 auto 15px; border: 2px solid var(--neon-blue); display: flex; align-items: center; justify-content: center; box-shadow: 0 0 20px rgba(14, 165, 233, 0.2); transition: 0.3s; }        .ai-eye { width: 40px; height: 40px; background: var(--neon-blue); border-radius: 50%; animation: breathe 3s infinite; transition: 0.3s; }        @keyframes breathe { 0%,100% { transform: scale(0.8); opacity:0.8; } 50% { transform: scale(1.1); opacity:1; } }        .terminal { font-family: var(--font-tech); font-size: 0.8rem; flex: 1; display: flex; flex-direction: column; justify-content: flex-end; min-height: 200px; }        .log-entry { margin-bottom: 5px; animation: slideIn 0.3s; }        .log-time { color: var(--text-dim); margin-right: 8px; }        @keyframes slideIn { from { opacity:0; transform:translateX(-10px); } to { opacity:1; transform:translateX(0); } }        .kpi-container { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 20px; }        .stat-box { background: rgba(255,255,255,0.03); padding: 20px; border-radius: 8px; border-left: 4px solid transparent; transition: 0.3s; }        .stat-temp { border-color: var(--neon-blue); }        .stat-weight { border-color: var(--neon-gold); }        .stat-val { font-size: 2.5rem; font-weight: 700; color: #fff; margin: 5px 0; }        .stat-lbl { font-size: 0.7rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 1px; }        .chart-wrapper { flex: 1; position: relative; min-height: 350px; }        .harvest-bg { width: 100%; height: 6px; background: rgba(255,255,255,0.1); margin-top: 10px; border-radius: 10px; }        .harvest-fill { height: 100%; background: var(--neon-gold); width: 0%; transition: width 1s; box-shadow: 0 0 10px var(--neon-gold); }        @media screen and (max-width: 1024px) { .dash-grid { display: flex !important; flex-direction: column !important; gap: 20px; } .right-panel { height: auto !important; } .chart-wrapper { min-height: 400px !important; } }        @media screen and (max-width: 768px) { .kpi-container { grid-template-columns: 1fr !important; } .page-header { display: flex; flex-direction: column; align-items: stretch; gap: 15px; } .page-header > div:last-child { width: 100% !important; } #hiveSelect { width: 100%; padding: 15px; font-size: 1.1rem; } .stat-val { font-size: 2rem; } }    </style></head><body>    <div class="app-wrapper">        <aside class="sidebar">            <div class="sidebar-brand"><i class="fas fa-hexagon-nodes"></i> BEE_WEB</div>            <nav class="sidebar-menu">                <a href="index.php" class="nav-item"><i class="fas fa-th-large"></i> DASHBOARD</a>                <a href="carte.php" class="nav-item"><i class="fas fa-globe-americas"></i> SATELLITE</a>                <a href="monitoring.php" class="nav-item active"><i class="fas fa-wave-square"></i> MONITORING AI</a>                <a href="historique.php" class="nav-item"><i class="fas fa-history"></i> ARCHIVES</a>                <a href="parametres.php" class="nav-item"><i class="fas fa-cogs"></i> SYSTÈME</a>                <a href="logout.php" class="nav-item" style="color: #ef4444; margin-top: 20px; border-top: 1px solid #ef4444; padding-top: 15px;"><i class="fas fa-power-off"></i> DÉCONNEXION</a>            </nav>            <div class="sys-footer">STATUS: ONLINE<br>ENCRYPTION: AES-256</div>        </aside>        <main class="main-content">            <header class="page-header" style="display: flex; justify-content: space-between; align-items: center; width: 100%;">                <div class="page-title">                    <h2 style="margin: 0;">SUPERVISION <b>MELAINA</b></h2>                    <p class="page-subtitle" style="margin: 5px 0 0 0;">T: <span id="clock">--:--:--</span> // STATUT: <span style="color:var(--neon-blue)">SYSTÈME ACTIF</span></p>                </div>                                <div style="display: flex; gap: 15px; align-items: center;">                    <?php if(count($mes_ruches) > 0): ?>                        <select id="hiveSelect" class="hive-selector" onchange="switchHive(this.value)" style="background: rgba(0,0,0,0.5); color: white; border: 1px solid var(--neon-blue); padding: 8px 15px; border-radius: 6px; cursor: pointer;">                            <?php if(in_array(1, $mes_ruches)): ?>                                <option value="alpha">ALPHA-01 (Mère - Simulée)</option>                            <?php endif; ?>                            <?php if(in_array(2, $mes_ruches)): ?>                                <option value="beta">BETA-VORTEX (Fille - LIVE)</option>                            <?php endif; ?>                        </select>                                                <a href="carte.php" id="btn-loc" style="display: flex; align-items: center; gap: 8px; padding: 10px 20px; background: rgba(14, 165, 233, 0.1); border: 1px solid var(--neon-blue); color: var(--neon-blue); border-radius: 6px; text-decoration: none; font-weight: bold; font-size: 0.85rem; transition: 0.3s;">                            <i class="fas fa-satellite"></i> LOCALISATION                        </a>                    <?php else: ?>                        <span style="color:#ef4444; font-size:0.8rem; border:1px solid #ef4444; padding:5px 10px; border-radius:4px;">ACCÈS RESTREINT</span>                    <?php endif; ?>                </div>            </header>            <?php if(count($mes_ruches) > 0): ?>            <div class="dash-grid">                <div class="cyber-card">                    <div class="ai-status">                        <div class="ai-avatar" id="ai-avatar-box"><div class="ai-eye" id="ai-eye-color"></div></div>                        <div style="color:var(--neon-blue); font-weight:bold; letter-spacing:1px;" id="ai-title">IA ANALYTICS v9.2</div>                        <div style="font-size:0.8rem; color:var(--text-dim); margin-top:5px;" id="ai-mode">INITIALISATION...</div>                    </div>                    <div class="terminal" id="terminal"></div>                </div>                <div class="right-panel">                    <div class="kpi-container">                        <div class="stat-box stat-temp" id="box-temp">                            <div class="stat-lbl">TEMPÉRATURE COEUR</div>                            <div class="stat-val" id="val-temp">--°C</div>                            <div style="font-size:0.8rem; color:var(--text-dim);" id="msg-temp">Plage optimale: <?php echo $seuil_froid; ?>°C - <?php echo $seuil_chaud; ?>°C</div>                        </div>                        <div class="stat-box stat-weight">                            <div style="display:flex; justify-content:space-between;">                                <div class="stat-lbl">MASSE TOTALE</div>                                <div style="color:var(--neon-gold); font-size:0.75rem; font-weight:bold;" id="pct-text">0%</div>                            </div>                            <div class="stat-val" id="val-weight">--kg</div>                            <div class="harvest-bg"><div class="harvest-fill" id="bar-fill"></div></div>                            <div style="font-size:0.75rem; color:var(--neon-gold); margin-top:5px; font-weight:bold;" id="harvest-msg">Calcul...</div>                        </div>                    </div>                    <div class="cyber-card chart-wrapper">                        <div style="position:absolute; top:15px; left:20px; font-size:0.75rem; color:var(--text-dim); font-family:var(--font-tech);">// FLUX DONNÉES TEMPS RÉEL</div>                        <canvas id="cyberChart"></canvas>                    </div>                </div>            </div>            <?php else: ?>                <div style="text-align:center; padding:100px; background:rgba(255,255,255,0.05); border-radius:12px; margin-top:30px;">                    <i class="fas fa-lock" style="font-size:3rem; color:#64748b; margin-bottom:20px;"></i>                    <h3 style="color:var(--neon-blue);">MONITORING HORS LIGNE</h3>                    <p>Veuillez contacter l'administrateur pour lier une unité à votre compte.</p>                </div>            <?php endif; ?>        </main>    </div>    <?php if(count($mes_ruches) > 0): ?>    <script>        // --- 1. IMPORTATION DES SEUILS DYNAMIQUES DEPUIS PHP ---        const seuilFroid = <?php echo $seuil_froid; ?>;        const seuilChaud = <?php echo $seuil_chaud; ?>;        // --- 2. SYSTEM CLOCK ---        setInterval(() => {            const now = new Date();            document.getElementById('clock').innerText = now.toLocaleTimeString('fr-FR');        }, 1000);        // --- 3. CONFIG CHART ---        const ctx = document.getElementById('cyberChart').getContext('2d');        let gradient = ctx.createLinearGradient(0, 0, 0, 400);        gradient.addColorStop(0, 'rgba(14, 165, 233, 0.4)'); gradient.addColorStop(1, 'rgba(14, 165, 233, 0)');        const chart = new Chart(ctx, {            type: 'line',            data: {                labels: [],                datasets: [                    { data: [], borderColor: '#0ea5e9', backgroundColor: gradient, borderWidth: 2, pointRadius:0, fill: true, tension: 0.4, yAxisID: 'y' },                    { data: [], borderColor: '#f59e0b', borderWidth: 2, borderDash: [5,5], pointRadius:0, tension: 0.4, yAxisID: 'y1' }                ]            },            options: {                responsive: true, maintainAspectRatio: false, animation: false,                plugins: { legend: { display: false } },                scales: {                    x: { display: false },                    y: { position: 'left', grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#64748b' } },                    y1: { position: 'right', display: false }                }            }        });        // --- 4. DATA & LOGIC ---        const hives = {            'alpha': {                 temp: 34.8, // Température simulée ajustée pour être "optimale"                weight: 42.8, pct: 95, hMsg: "RÉCOLTE IMMINENTE",                 logs: ["Densité miel: 99%", "Activité reine: OK", "Propolis stable"], color: '#0ea5e9'             },            'beta': {                 temp: <?php echo $temp_beta; ?>, weight: <?php echo $poids_beta; ?>, pct: <?php echo $pct_beta; ?>,                 hMsg: "<?php echo $hMsg_beta; ?>",                 logs: ["Synchronisation BDD...", "Scan thermique en cours", "Activité capteurs OK"], color: '#10b981'             }        };        let currentId = document.getElementById('hiveSelect') ? document.getElementById('hiveSelect').value : null;        let curTemp = currentId ? hives[currentId].temp : 0;         let curWeight = currentId ? hives[currentId].weight : 0;        function tick() {            if(!currentId) return;            const chaos = currentId === 'beta' ? 0.6 : 0.1;            curTemp += (Math.random() - 0.5) * chaos;            curWeight += (Math.random() - 0.5) * 0.02;                        const base = hives[currentId].temp;            if(curTemp > base+1) curTemp -= 0.1; if(curTemp < base-1) curTemp += 0.1;            document.getElementById('val-temp').innerText = curTemp.toFixed(1) + '°C';            document.getElementById('val-weight').innerText = curWeight.toFixed(1) + 'kg';                        const tMsg = document.getElementById('msg-temp');            const boxTemp = document.getElementById('box-temp');            const aiEye = document.getElementById('ai-eye-color');            const aiAvatar = document.getElementById('ai-avatar-box');            const aiTitle = document.getElementById('ai-title');            // --- IA : GESTION DES NOUVEAUX SEUILS FROID / CHAUD ---            if(curTemp >= seuilChaud) {                 // ALERTE SURCHAUFFE (ROUGE)                tMsg.innerHTML = "⚠ SURCHAUFFE (> " + seuilChaud + "°C)";                 tMsg.style.color = "var(--neon-red)";                 boxTemp.style.borderColor = "var(--neon-red)";                aiEye.style.background = "var(--neon-red)";                aiAvatar.style.borderColor = "var(--neon-red)";                aiAvatar.style.boxShadow = "0 0 20px rgba(239, 68, 68, 0.4)";                aiTitle.style.color = "var(--neon-red)";                document.getElementById('ai-mode').innerText = "MODE: ALERTE CHAUD";                chart.data.datasets[0].borderColor = '#ef4444';             } else if (curTemp <= seuilFroid) {                // ALERTE HYPOTHERMIE (BLEU GLACE)                tMsg.innerHTML = "❄ HYPOTHERMIE (< " + seuilFroid + "°C)";                 tMsg.style.color = "#38bdf8";                 boxTemp.style.borderColor = "#38bdf8";                aiEye.style.background = "#38bdf8";                aiAvatar.style.borderColor = "#38bdf8";                aiAvatar.style.boxShadow = "0 0 20px rgba(56, 189, 248, 0.4)";                aiTitle.style.color = "#38bdf8";                document.getElementById('ai-mode').innerText = "MODE: ALERTE FROID";                chart.data.datasets[0].borderColor = '#38bdf8';             } else {                 // ÉTAT NORMAL (OPTIMAL)                tMsg.innerHTML = "Régulation optimale (" + seuilFroid + "°C - " + seuilChaud + "°C)";                 tMsg.style.color = "var(--text-dim)";                 boxTemp.style.borderColor = hives[currentId].color;                aiEye.style.background = hives[currentId].color;                aiAvatar.style.borderColor = hives[currentId].color;                aiAvatar.style.boxShadow = "0 0 20px rgba(14, 165, 233, 0.2)";                aiTitle.style.color = hives[currentId].color;                document.getElementById('ai-mode').innerText = "MODE: OPTIMAL";                chart.data.datasets[0].borderColor = hives[currentId].color;             }            chart.data.labels.push('');            chart.data.datasets[0].data.push(curTemp);            chart.data.datasets[1].data.push(curWeight);            if(chart.data.labels.length > 40) {                chart.data.labels.shift(); chart.data.datasets[0].data.shift(); chart.data.datasets[1].data.shift();            }            chart.update();        }        function addLog() {            if(!currentId) return;            const term = document.getElementById('terminal');            const msgs = hives[currentId].logs;            const msg = msgs[Math.floor(Math.random()*msgs.length)];            const div = document.createElement('div');            div.className = 'log-entry';                        // Le terminal s'adapte aussi aux nouvelles couleurs d'alerte !            let logColor = `color:${hives[currentId].color}`;            if(curTemp >= seuilChaud) logColor = 'color:var(--neon-red)';            else if (curTemp <= seuilFroid) logColor = 'color:#38bdf8';            div.innerHTML = `<span class="log-time">[${new Date().toLocaleTimeString('fr-FR')}]</span> <span style="${logColor}">> ${msg}</span>`;            term.appendChild(div);            if(term.children.length > 8) term.removeChild(term.firstChild);        }        window.switchHive = function(id) {            currentId = id;            const btnLoc = document.getElementById('btn-loc');            if(btnLoc) { btnLoc.href = 'carte.php?hive=' + id; }            const h = hives[id];            curTemp = h.temp; curWeight = h.weight;                         document.getElementById('bar-fill').style.width = h.pct + "%";            document.getElementById('pct-text').innerText = h.pct + "% PRÊT";            document.getElementById('harvest-msg').innerText = h.hMsg;            if (document.getElementById('hiveSelect')) { document.getElementById('hiveSelect').value = id; }            chart.data.datasets[0].data = []; chart.data.datasets[1].data = [];             document.getElementById('terminal').innerHTML = "";         }        window.onload = function() {            const urlParams = new URLSearchParams(window.location.search);            const hiveParam = urlParams.get('hive');                        if(hiveParam && hives[hiveParam] && document.getElementById('hiveSelect')) {                let optionExists = Array.from(document.getElementById('hiveSelect').options).some(opt => opt.value === hiveParam);                if (optionExists) {                    switchHive(hiveParam);                } else {                    switchHive(document.getElementById('hiveSelect').value);                }            } else if (document.getElementById('hiveSelect')) {                switchHive(document.getElementById('hiveSelect').value);            }            setInterval(tick, 800);            setInterval(addLog, 2000);        };    </script>    <?php endif; ?></body></html>